html:
{#- =====================================================================
    POS Invoice print format (127mm thermal style)
    All business data is dynamic:
      - Store address / phone / email / brand / tagline / QR : POS Profile -> Company Address
      - Mobile / Instagram / Website                          : POS Profile custom fields
      - Terms and Conditions                                  : POS Profile -> tc_name
===================================================================== -#}

{#- ---------- Company / POS Profile / store address ---------- -#}
{%- set co = frappe.get_doc("Company", doc.company) -%}
{%- set pos = frappe.get_doc("POS Profile", doc.pos_profile) if doc.pos_profile else None -%}
{%- set store = frappe.get_doc("Address", pos.company_address) if (pos and pos.company_address) else None -%}
{#- ---------- Custom fields lookup (works with any custom_* fieldname) ---------- -#}
{%- set pd = pos.as_dict() if pos else {} -%}
{%- set sd = store.as_dict() if store else {} -%}
{%- set pf = namespace(mobile="", insta="", web="") -%}
{%- for k, v in pd.items() -%}
  {%- if v and k.startswith("custom_") -%}
    {%- if "mobile" in k or "phone" in k -%}{%- set pf.mobile = v -%}{%- endif -%}
    {%- if "insta" in k -%}{%- set pf.insta = v -%}{%- endif -%}
    {%- if "website" in k or "web" in k -%}{%- set pf.web = v -%}{%- endif -%}
  {%- endif -%}
{%- endfor -%}
{%- set sf = namespace(brand="", tagline="", qr="") -%}
{%- for k, v in sd.items() -%}
  {%- if v and k.startswith("custom_") -%}
    {%- if "brand" in k -%}{%- set sf.brand = v -%}{%- endif -%}
    {%- if "tagline" in k -%}{%- set sf.tagline = v -%}{%- endif -%}
    {%- if "qr" in k -%}{%- set sf.qr = v -%}{%- endif -%}
  {%- endif -%}
{%- endfor -%}

{#- ---------- Branding ---------- -#}
{%- set brand = (pos.get("custom_brand_name") if pos else None) or sf.brand or co.company_name -%}
{%- set tagline = (pos.get("custom_tagline") if pos else None) or sf.tagline or co.company_description or "Empowering You" -%}
{%- set qr_image = sf.qr or "/assets/franchise_erp/images/ikshita_qr.png" -%}
{%- set parent_name = (frappe.db.get_value("Company", co.parent_company, "company_name") if co.parent_company else None) or co.company_name -%}
{%- set jurisdiction = (store.city if store and store.city else "") -%}

{#- ---------- POS Profile values (scan section) ---------- -#}
{%- set p_mobile = pf.mobile or "" -%}
{%- set p_insta = pf.insta or "" -%}
{%- set p_web = (pf.web or "") | replace("https://", "") | replace("http://", "") -%}

{#- ---------- Terms and Conditions (POS Profile -> tc_name) ---------- -#}
{%- set tc_name = (pos.tc_name if pos else None) or doc.tc_name -%}
{%- set tc_terms = (frappe.db.get_value("Terms and Conditions", tc_name, "terms") if tc_name else None) or doc.terms -%}

{#- ---------- Registered office address ---------- -#}
{%- set reg_links = frappe.get_all("Dynamic Link", filters={"link_doctype": "Company", "link_name": doc.company, "parenttype": "Address"}, fields=["parent"]) -%}
{%- set reg = namespace(a=None) -%}
{%- for l in reg_links -%}
  {%- if not reg.a -%}{%- set reg.a = frappe.get_doc("Address", l.parent) -%}{%- endif -%}
  {%- if frappe.db.get_value("Address", l.parent, "address_type") == "Office" -%}{%- set reg.a = frappe.get_doc("Address", l.parent) -%}{%- endif -%}
{%- endfor -%}

{%- set cur_symbol = frappe.db.get_value("Currency", doc.currency, "symbol") or doc.currency -%}
{%- set lh_footer = frappe.db.get_value("Letter Head", doc.letter_head, "footer") if doc.letter_head else "" -%}
{%- set cashier = frappe.db.get_value("User", doc.owner, "full_name") or doc.owner -%}
{%- set emp_no = frappe.db.get_value("Employee", {"user_id": doc.owner}, "employee_number") or frappe.db.get_value("Employee", {"user_id": doc.owner}, "name") -%}
{%- set mobile = doc.contact_mobile or frappe.db.get_value("Customer", doc.customer, "custom_mobile_no_customer") or frappe.db.get_value("Customer", doc.customer, "mobile_no") or "" -%}
{%- set net_payable = doc.rounded_total or doc.grand_total -%}

{#- ---------- Flags from taxes table ---------- -#}
{%- set flags = namespace(incl=false, igst=false, fallback_rate=0) -%}
{%- for tx in doc.taxes -%}
  {%- set head = (tx.account_head or "") | lower -%}
  {%- if tx.included_in_print_rate -%}{%- set flags.incl = true -%}{%- endif -%}
  {%- if "igst" in head -%}{%- set flags.igst = true -%}{%- endif -%}
  {%- set flags.fallback_rate = flags.fallback_rate + (tx.rate or 0) -%}
{%- endfor -%}

{%- set paid_rows = [] -%}
{%- for p in doc.payments -%}
  {%- if p.amount -%}{%- set _ = paid_rows.append(p) -%}{%- endif -%}
{%- endfor -%}

{#- ---------- Totals / GST summary (India Compliance item fields) ---------- -#}
{%- set tot = namespace(gross=0, qty=0, disc=0, half=0, mixed=false) -%}
{%- set hsn_map = {} -%}
{%- set item_gst = {} -%}

{%- for it in doc.items -%}
  {%- set mrp = it.price_list_rate or it.rate -%}
  {%- set tot.gross = tot.gross + (mrp * it.qty) -%}
  {%- set tot.qty = tot.qty + it.qty -%}
  {%- set tot.disc = tot.disc + ((mrp * it.qty) - it.amount) -%}

  {%- set c_amt = it.get("cgst_amount") or 0 -%}
  {%- set s_amt = it.get("sgst_amount") or 0 -%}
  {%- set i_amt = it.get("igst_amount") or 0 -%}
  {%- set c_rate = it.get("cgst_rate") or 0 -%}
  {%- set s_rate = it.get("sgst_rate") or 0 -%}
  {%- set i_rate = it.get("igst_rate") or 0 -%}
  {%- set pct = (c_rate + s_rate + i_rate) or flags.fallback_rate -%}
  {%- set _ = item_gst.update({it.name: pct}) -%}

  {%- if c_rate -%}
    {%- if tot.half and tot.half != c_rate -%}{%- set tot.mixed = true -%}{%- endif -%}
    {%- set tot.half = c_rate -%}
  {%- endif -%}

  {%- set h = it.gst_hsn_code or "-" -%}
  {%- if h not in hsn_map -%}
    {%- set _ = hsn_map.update({h: {"taxable": 0, "cgst": 0, "sgst": 0, "igst": 0}}) -%}
  {%- endif -%}
  {%- set taxable = it.get("taxable_value") or it.net_amount or it.amount -%}
  {%- set _ = hsn_map[h].update({"taxable": hsn_map[h]["taxable"] + taxable, "cgst": hsn_map[h]["cgst"] + c_amt, "sgst": hsn_map[h]["sgst"] + s_amt, "igst": hsn_map[h]["igst"] + i_amt}) -%}
  {%- if i_amt -%}{%- set flags.igst = true -%}{%- endif -%}
{%- endfor -%}

{#- PAGE SIZE: applies to this print format only. Change 127mm / 297mm here if needed. -#}
<meta name="pdfkit-page-width" content="127mm">
<meta name="pdfkit-page-height" content="297mm">
<meta name="pdfkit-margin-top" content="0mm">
<meta name="pdfkit-margin-bottom" content="0mm">
<meta name="pdfkit-margin-left" content="0mm">
<meta name="pdfkit-margin-right" content="0mm">

<style>
  @import url('https://fonts.googleapis.com/css2?family=Playfair+Display:wght@600;700;800&family=IBM+Plex+Sans:wght@400;500;600;700&display=swap');
  @page { size: 127mm 297mm; margin: 0; }

  .ik-bill { font-family:'IBM Plex Sans',Arial,Helvetica,sans-serif; font-size:9.5pt; line-height:1.5; color:#111;
             width:127mm; max-width:100%; margin:0 auto; padding:8mm; box-sizing:border-box; }
  .ik-bill * { box-sizing:border-box; }
  .ik-bill .center { text-align:center; }
  .ik-bill .right  { text-align:right; }
  .ik-bill .bold   { font-weight:700; }

  .ik-bill .brand  { font-family:'Playfair Display',Georgia,serif; font-size:34pt; font-weight:800; line-height:1.1; margin:2pt 0 0; }
  .ik-bill .tagline{ font-size:6.5pt; letter-spacing:4.5pt; font-weight:600; margin:2pt 0 9pt; text-transform:uppercase; }
  .ik-bill .store-name { font-weight:700; font-size:10pt; margin-top:9pt; }

  .ik-bill .dash  { border-top:1px dashed #000; margin:7pt 0; }
  .ik-bill .solid { border-top:1px solid #000; margin:4pt 0; }
  .ik-bill .title { font-size:14pt; font-weight:700; letter-spacing:3pt; text-align:center; margin:4pt 0; }

  .ik-bill table { width:100%; border-collapse:collapse; }
  .ik-bill td, .ik-bill th { padding:1.5pt 0; vertical-align:top; }
  .ik-bill .meta td:nth-child(2) { text-align:right; }

  .ik-bill .items th { font-size:8.5pt; font-weight:700; border-bottom:1px solid #000; padding-bottom:3pt; text-align:right; }
  .ik-bill .items th:first-child, .ik-bill .items td:first-child { text-align:left; }
  .ik-bill .items td { text-align:right; }
  .ik-bill .item-name { font-weight:700; font-size:9.5pt; }
  .ik-bill .item-sub  { font-size:8.7pt; line-height:1.45; margin-top:4pt; text-align:left; }

  .ik-bill .totals td { font-size:10.5pt; padding:2pt 0; }
  .ik-bill .totals td:last-child, .ik-bill .pay td:last-child, .ik-bill .net td:last-child { text-align:right; }
  .ik-bill .net td { font-size:16pt; font-weight:800; padding:4pt 0; }

  .ik-bill .gst th { font-size:8pt; font-weight:700; border-bottom:1px solid #000; text-align:right; }
  .ik-bill .gst th:first-child, .ik-bill .gst td:first-child { text-align:left; }
  .ik-bill .gst td { font-size:8.7pt; text-align:right; }

  .ik-bill .sec-title { font-weight:700; font-size:9.5pt; margin-bottom:3pt; text-transform:uppercase; }
  .ik-bill .pay td { font-size:10.5pt; }
  .ik-bill .policy { font-size:8.7pt; margin:1pt 0; }
  .ik-bill .policy p, .ik-bill .policy div { margin:1pt 0; }
  .ik-bill .policy ul, .ik-bill .policy ol { margin:0; padding-left:14pt; }

  .ik-bill .follow { display:flex; align-items:center; }
  .ik-bill .follow img { width:26mm; height:26mm; margin-right:4mm; }
  .ik-bill .follow .txt { font-size:9pt; line-height:1.55; }

  .ik-bill .foot { text-align:center; font-size:8.5pt; }
  .ik-bill .thanks { font-family:'Playfair Display',Georgia,serif; font-size:15pt; font-weight:700; margin:6pt 0 2pt; }
</style>

<div class="ik-bill">

  <!-- ===== HEADER ===== -->
  <div class="center">
    <div class="brand">{{ brand }}</div>
    {%- if tagline %}<div class="tagline">{{ tagline }}</div>{%- endif %}
    <div style="font-size:10.5px;">A unit of {{ parent_name }}</div>

    <div class="store-name">{{ (store.address_title if store else None) or doc.pos_profile }}</div>
    <div>
      {%- if store %}
        {%- if pd.get("custom_pos_address") %}
        {{ pd.get("custom_pos_address") | replace("\n", "<br>") | safe }}<br>
        {%- else %}
        {{ (store.address_line1 or "").strip().rstrip(",") }}{% if store.address_line2 %}, {{ store.address_line2.strip().rstrip(",") }}{% endif %},<br>
        {{ store.city }}{% if store.pincode %} {{ store.pincode }}{% endif %}<br>
        {%- endif %}
        {%- if store.phone or store.email_id %}
        {% if store.phone %}Store Ph: {{ store.phone }}{% endif %}{% if store.phone and store.email_id %} &middot; {% endif %}{% if store.email_id %}{{ store.email_id }}{% endif %}<br>
        {%- endif %}
      {%- endif %}
      GSTIN: {{ doc.company_gstin or co.tax_id or "" }}
      {%- if store and store.state %} &middot; State: {{ store.state }}{% if store.get("gst_state_number") %} ({{ store.gst_state_number }}){% endif %}{% endif %}
      {%- if reg.a %}<br>Regd. office: {{ (reg.a.address_line1 or "").strip().rstrip(",") }}{% if reg.a.address_line2 %}, {{ reg.a.address_line2.strip().rstrip(",") }}{% endif %}, {{ reg.a.city }}{% if reg.a.pincode %} {{ reg.a.pincode }}{% endif %}{%- endif %}
    </div>
  </div>

  <div class="dash"></div>
  <div class="title">{{ doc.select_print_heading or "TAX INVOICE" }}</div>
  <div class="dash"></div>

  <!-- ===== META ===== -->
  <table class="meta">
    <tr>
      <td><b>Invoice No:</b> {{ doc.name }}</td>
      <td><b>Date:</b> {{ frappe.utils.formatdate(doc.posting_date, "dd-MM-yyyy") }}</td>
    </tr>
    <tr>
      <td><b>Cashier:</b> {{ cashier }}{% if emp_no %} ({{ emp_no }}){% endif %}</td>
      <td><b>Time:</b> {{ frappe.utils.format_time(doc.posting_time, "hh:mm a") }}</td>
    </tr>
    <tr>
      <td><b>Customer:</b> {{ doc.customer_name }}</td>
      <td>{% if mobile %}<b>Mobile:</b> {{ mobile }}{% endif %}</td>
    </tr>
    <tr>
        <td colspan="2">{% if doc.place_of_supply %}<b>Place of supply:</b> {{ doc.place_of_supply }}{% endif %}</td>
    </tr>
  </table>

  <div class="dash"></div>

  <!-- ===== ITEMS ===== -->
  <table class="items">
    <thead>
      <tr><th style="width:36%;">Item</th><th>Qty</th><th>MRP</th><th>Disc</th><th>Amount</th></tr>
    </thead>
    <tbody>
      {%- for it in doc.items %}
      {%- set mrp = it.price_list_rate or it.rate -%}
{%- set attrs = frappe.get_all("Item Variant Attribute", filters={"parent": it.item_code, "parenttype": "Item"}, fields=["attribute", "attribute_value"], order_by="idx") -%}
{%- if not attrs -%}
  {%- set item_d = frappe.get_doc("Item", it.item_code).as_dict() -%}
  {%- set tmp = [] -%}
  {%- for k, v in item_d.items() -%}
    {%- if v and k.startswith("custom_") and ("size" in k or "colour" in k or "color" in k) -%}
      {%- set _ = tmp.append({"attribute": k.replace("custom_", "").replace("_", " ") | title, "attribute_value": v}) -%}
    {%- endif -%}
  {%- endfor -%}
  {%- set attrs = tmp -%}
{%- endif -%}      <tr>
        <td class="item-name">{{ it.item_name }}</td>
        <td>{{ "%g"|format(it.qty) }} {{ it.uom }}</td>
        <td>{{ "{:,.2f}".format(mrp) }}</td>
        <td>{{ "{:,.2f}".format((mrp * it.qty) - it.amount) }}</td>
        <td class="bold">{{ "{:,.2f}".format(it.amount) }}</td>
      </tr>
      <tr>
        <td colspan="5">
          <div class="item-sub">
            {%- for a in attrs %}{{ a.attribute }}: {{ a.attribute_value }}{% if not loop.last %} &middot; {% endif %}{% endfor %}
            {%- if attrs %}<br>{% endif %}
            SKU: {{ it.item_code }}{% if it.gst_hsn_code %} &middot; HSN: {{ it.gst_hsn_code }}{% endif %}<br>
            {%- if it.serial_no %}Sr. No: {{ it.serial_no.replace("\n", ", ") }}{% if item_gst.get(it.name) %} &middot; {% endif %}{% endif %}
            {%- if item_gst.get(it.name) %}GST {{ "%g"|format(item_gst[it.name]) }}%{% endif %}
          </div>
        </td>
      </tr>
      {%- endfor %}
    </tbody>
  </table>

  <div class="dash"></div>

  <!-- ===== TOTALS ===== -->
  <table class="totals">
    <tr><td>Total items / Qty</td><td>{{ doc.items | length }} / {{ "%g"|format(tot.qty) }}{% if doc.items %} {{ doc.items[0].uom }}{% endif %}</td></tr>
    <tr><td>Gross amount (MRP)</td><td>{{ cur_symbol }} {{ "{:,.2f}".format(tot.gross) }}</td></tr>
    <tr><td>Less: Discount</td><td>{{ cur_symbol }} {{ "{:,.2f}".format(tot.disc + (doc.discount_amount or 0)) }}</td></tr>
    <tr><td>Round off</td><td>{{ cur_symbol }} {{ "{:,.2f}".format(doc.rounding_adjustment or 0) }}</td></tr>
  </table>

  <div class="solid"></div>
  <table class="net"><tr><td>NET PAYABLE</td><td>{{ cur_symbol }} {{ "{:,.2f}".format(net_payable) }}</td></tr></table>
  <div class="solid"></div>

  {%- if flags.incl %}<div class="right" style="font-size:9.5px;">Prices inclusive of GST</div>{%- endif %}
  <div style="font-size:10.5px; margin-top:3px;">
    <b>In words:</b> {{ doc.in_words or frappe.utils.money_in_words(net_payable, doc.currency) }}
  </div>

  <div class="dash"></div>

  <!-- ===== GST SUMMARY ===== -->
  <div class="sec-title">GST SUMMARY</div>
  <table class="gst">
    <thead>
      <tr>
        <th>HSN</th><th>Taxable</th>
        {%- if flags.igst %}
        <th>IGST</th>
        {%- elif tot.mixed or not tot.half %}
        <th>CGST</th><th>SGST</th>
        {%- else %}
        <th>CGST {{ "%g"|format(tot.half) }}%</th><th>SGST {{ "%g"|format(tot.half) }}%</th>
        {%- endif %}
        <th>Total tax</th>
      </tr>
    </thead>
    <tbody>
      {%- for h, v in hsn_map.items() %}
      <tr>
        <td>{{ h }}</td>
        <td>{{ "{:,.2f}".format(v.taxable) }}</td>
        {%- if flags.igst %}
        <td>{{ "{:,.2f}".format(v.igst) }}</td>
        {%- else %}
        <td>{{ "{:,.2f}".format(v.cgst) }}</td><td>{{ "{:,.2f}".format(v.sgst) }}</td>
        {%- endif %}
        <td>{{ "{:,.2f}".format(v.cgst + v.sgst + v.igst) }}</td>
      </tr>
      {%- endfor %}
    </tbody>
  </table>

  <div class="dash"></div>

  <!-- ===== PAYMENT ===== -->
  <div class="sec-title">PAYMENT</div>
  <table class="pay">
    {%- for p in paid_rows %}
    <tr><td>Mode{% if paid_rows | length > 1 %} ({{ loop.index }}){% endif %}</td><td>{{ p.mode_of_payment }}</td></tr>
    {%- endfor %}
    <tr><td>Amount received</td><td>{{ cur_symbol }} {{ "{:,.2f}".format(doc.paid_amount or 0) }}</td></tr>
    <tr><td>Change returned</td><td>{{ cur_symbol }} {{ "{:,.2f}".format(doc.change_amount or 0) }}</td></tr>
  </table>

  <!-- ===== TERMS AND CONDITIONS (POS Profile -> tc_name) ===== -->
  {%- if tc_name or tc_terms %}
  <div class="dash"></div>
  <div class="sec-title">{{ tc_name or "TERMS AND CONDITIONS" }}</div>
  <div class="policy">{{ tc_terms | safe }}</div>
  {%- endif %}

  <!-- ===== FOLLOW US (POS Profile custom fields + Address QR) ===== -->
  {%- if qr_image or p_mobile or p_insta or p_web or (store and store.email_id) %}
  <div class="dash"></div>
  <div class="follow">
{%- if qr_image %}<img src="{{ qr_image }}" alt="QR">{%- endif %}
    <div class="txt">
      <b>Scan to follow us</b><br>
      {%- if p_insta %}{{ p_insta }}<br>{% endif %}
      {%- if p_web %}{{ p_web }}<br>{% endif %}
      {%- if store and store.email_id %}Email : {{ store.email_id }}<br>{% endif %}
      {%- if p_mobile %}Number: {{ p_mobile }}{% endif %}
    </div>
  </div>
  {%- endif %}

  <!-- ===== FOOTER (Letter Head footer, otherwise default) ===== -->
  <div class="dash"></div>
  <div class="foot">
    {%- if lh_footer %}
      {{ lh_footer }}
    {%- else %}
      <div class="thanks">Thank you for shopping with {{ brand }}</div>
      <div>This is a computer-generated invoice.</div>
      <div>E. &amp; O.E.{% if jurisdiction %} &middot; Subject to {{ jurisdiction }} jurisdiction{% endif %}</div>
    {%- endif %}
  </div>

</div>
